      const queryUser = currentUser?.uid ? `&user_id=${currentUser.uid}` : '';
      fetch(`/api/stripe/verify-session?session_id=${sessionId}&tier=${tier}${queryUser}`)
        .then((res) => res.json())
        .then((data) => {
          if (data.valid) {
            handleUpdateProfileTier(tier as any, {
              stripeCustomerId: data.stripeCustomerId,
              stripeSubscriptionId: data.stripeSubscriptionId,
              membershipStatus: data.membershipStatus || 'active',
              paymentStatus: 'paid',
            });
            setIsPatronModalOpen(true);
            // Clean URL params
            window.history.replaceState({}, document.title, window.location.pathname);
          }
        })
        .catch((err) => console.error('Error verifying Stripe return session:', err));
    }
  }, [currentUser]);

  // Sync profile state with localStorage and Firestore
  useEffect(() => {
    localStorage.setItem('centerflow_profile', JSON.stringify(userProfile));
    if (currentUser) {
      const userDocRef = doc(db, 'users', currentUser.uid);
      setDoc(userDocRef, userProfile, { merge: true }).catch((e) =>
        console.error('Error syncing profile to Firestore:', e)
      );
    }
  }, [userProfile, currentUser]);

  const activeTab: TabType = screen.type === 'tab' ? screen.tab : 'home';

  const navigateTo = (nextScreen: ScreenView) => {
    setScreenHistory((prev) => [...prev, screen]);
    setScreen(nextScreen);
  };

  const handleGoBack = () => {
    if (screenHistory.length > 0) {
      const prevScreen = screenHistory[screenHistory.length - 1];
      setScreenHistory((prev) => prev.slice(0, prev.length - 1));
      setScreen(prevScreen);
    } else {
      setScreen({ type: 'tab', tab: 'home' });
    }
  };

  const handleNavigateHome = () => {
    setScreenHistory([]);
    setScreen({ type: 'tab', tab: 'home' });
  };

  const handleTabChange = (tab: TabType) => {
    if (screen.type === 'tab' && screen.tab === tab) return;
    navigateTo({ type: 'tab', tab });
  };

  const handleSearchQueryFromHome = (query: string) => {
    setSearchQuery(query);
    navigateTo({ type: 'tab', tab: 'search' });
  };

  const handleSelectRoutine = (routineId: string) => {
    navigateTo({ type: 'routine_detail', routineId });
  };

  const handleSelectStretch = (stretchId: string) => {
    navigateTo({ type: 'stretch_detail', stretchId });
  };

  const handleStartTimer = (routineId?: string, stretchId?: string) => {
    navigateTo({ type: 'active_timer', routineId, stretchId });
  };

  const handleUpdateProfileTier = (
    tierId: 'supporter' | 'guardian' | 'pass',
    extraDetails?: Partial<UserProfile>
  ) => {
    setUserProfile((prev) => ({
      ...prev,
      patronTier: tierId,
      ...extraDetails,
    }));
  };

  const handleToggleSaveStretch = (stretchId: string) => {
    setUserProfile((prev) => {
      const isSaved = prev.savedStretchIds.includes(stretchId);
      const newSaved = isSaved
        ? prev.savedStretchIds.filter((id) => id !== stretchId)
        : [...prev.savedStretchIds, stretchId];
      return { ...prev, savedStretchIds: newSaved };
    });
  };

  const handleCompleteSession = (minutes: number, sessionTitle: string) => {
    setUserProfile((prev) => {
      const newActivity = [
        {
          id: `act-${Date.now()}`,
          title: sessionTitle,
          dateLabel: `Just now • ${minutes} min`,
          durationMinutes: minutes,
          timestamp: Date.now(),
          iconType: 'self_improvement' as const,
        },
        ...prev.recentActivity,
      ];
      return {
        ...prev,
        totalStretches: prev.totalStretches + 1,
        minutesRelaxed: prev.minutesRelaxed + minutes,
        recentActivity: newActivity,
      };
    });
    setScreen({ type: 'tab', tab: 'profile' });
  };

  const handleToggleSetting = (key: keyof UserProfile['settings']) => {
    setUserProfile((prev) => ({
      ...prev,
      settings: {
        ...prev.settings,
        [key]: !prev.settings[key],
      },
    }));
  };

  const savedStretchesList = STRETCHES_DATA.filter((s) =>
    userProfile.savedStretchIds.includes(s.id)
  );

  return (
    <div className="min-h-screen bg-[#0F0F10] text-gray-200 flex flex-col font-sans">
      {/* Desktop & Mobile Header */}
      {screen.type !== 'active_timer' && (
        <Header
          title={
            screen.type === 'routine_detail'
              ? 'Routine Details'
              : screen.type === 'stretch_detail'
              ? 'Movement Focus'
              : screen.type === 'philosophy'
              ? 'Movement Guidance'
              : 'CenterFlow'
          }
          showBack={screen.type !== 'tab' || screen.tab !== 'home'}
          onBack={handleGoBack}
          onNavigateHome={handleNavigateHome}
          profileAvatarUrl={userProfile.avatarUrl}
          onProfileClick={() => handleTabChange('profile')}
          onPatronClick={() => setIsPatronModalOpen(true)}
        />
      )}

      {/* Main View Switcher */}
      <main className="flex-1">
        {screen.type === 'tab' && screen.tab === 'home' && (
          <HomeScreen
            userName={userProfile.name}
            userAvatarUrl={userProfile.avatarUrl}
            onSelectRoutine={handleSelectRoutine}
            onSelectStretch={handleSelectStretch}
            onStartTimer={handleStartTimer}
            onSearchQuery={handleSearchQueryFromHome}
            onOpenPatronModal={() => setIsPatronModalOpen(true)}
            routines={ROUTINES_DATA}
            stretches={STRETCHES_DATA}
          />
        )}

        {screen.type === 'tab' && screen.tab === 'search' && (
          <SearchScreen
            initialQuery={searchQuery}
            onSelectRoutine={handleSelectRoutine}
            onSelectStretch={handleSelectStretch}
            routines={ROUTINES_DATA}
            stretches={STRETCHES_DATA}
          />
        )}

        {screen.type === 'tab' && screen.tab === 'routines' && (
          <RoutinesScreen
            onSelectRoutine={(routine) => handleSelectRoutine(routine.id)}
            onSelectPhilosophy={() => navigateTo({ type: 'philosophy' })}
            routines={ROUTINES_DATA}
          />
        )}

        {screen.type === 'tab' && screen.tab === 'profile' && (
          <ProfileScreen
            userProfile={userProfile}
            onToggleSetting={handleToggleSetting}
            onOpenSavedStretches={() => setIsSavedModalOpen(true)}
            onOpenPatronModal={() => setIsPatronModalOpen(true)}
            onLogout={() => {
              if (window.confirm('Reset local progress?')) {
                localStorage.removeItem('centerflow_profile');
                setUserProfile(INITIAL_PROFILE);
              }
            }}
          />
        )}

        {screen.type === 'philosophy' && (
          <PhilosophyScreen
            onBack={handleGoBack}
            onStartJourney={() => handleTabChange('routines')}
          />
        )}

        {screen.type === 'routine_detail' && (
          <RoutineDetailScreen
            routine={
              ROUTINES_DATA.find((r) => r.id === screen.routineId) || ROUTINES_DATA[0]
            }
            onBack={handleGoBack}
            onStartRoutine={(routineId) => handleStartTimer(routineId, undefined)}
            onSelectStretch={handleSelectStretch}
            onSearchQuery={handleSearchQueryFromHome}
          />
        )}

        {screen.type === 'stretch_detail' && (
          <StretchDetailScreen
            stretch={
              STRETCHES_DATA.find((s) => s.id === screen.stretchId) || STRETCHES_DATA[0]
            }
            onBack={handleGoBack}
            onStartStretchTimer={(stretchId) => handleStartTimer(undefined, stretchId)}
            onToggleSave={handleToggleSaveStretch}
            isSaved={userProfile.savedStretchIds.includes(screen.stretchId)}
            onSearchQuery={handleSearchQueryFromHome}
          />
        )}

        {screen.type === 'active_timer' && (
          <ActiveTimerModal
            routine={ROUTINES_DATA.find((r) => r.id === screen.routineId)}
            stretch={STRETCHES_DATA.find((s) => s.id === screen.stretchId)}
            initialStepIndex={screen.initialStepIndex || 0}
            onClose={handleGoBack}
            onCompleteSession={handleCompleteSession}
          />
        )}
      </main>

      {/* Saved Stretches Sheet Modal */}
      {isSavedModalOpen && (
        <SavedStretchesModal
          savedStretches={savedStretchesList}
          onClose={() => setIsSavedModalOpen(false)}
          onSelectStretch={handleSelectStretch}
        />
      )}

      {/* Patron & Gift Membership Modal */}
      <PatronModal
        isOpen={isPatronModalOpen}
        onClose={() => setIsPatronModalOpen(false)}
        currentUser={currentUser}
        userProfile={userProfile}
        onOpenAuth={() => setIsAuthModalOpen(true)}
        onUpdateProfileTier={handleUpdateProfileTier}
      />

      {/* Auth Modal */}
      <AuthModal
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        currentUser={currentUser}
      />

      {/* Glassmorphism Bottom Navigation for Mobile */}
      {screen.type !== 'active_timer' && (
        <BottomNav activeTab={activeTab} onTabChange={handleTabChange} />
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { MovementStep, Routine, Stretch } from '../types';
import { sound } from '../lib/audio';
import { STRETCHES_DATA } from '../data/stretchesData';

interface ActiveTimerModalProps {
  routine?: Routine;
  stretch?: Stretch;
  initialStepIndex?: number;
  onClose: () => void;
  onCompleteSession: (minutes: number, title: string) => void;
}

export const ActiveTimerModal: React.FC<ActiveTimerModalProps> = ({
  routine,
  stretch,
  initialStepIndex = 0,
  onClose,
  onCompleteSession,
}) => {
  // Steps queue
  const steps: { title: string; durationSeconds: number; description: string; arturoCue?: string; imageUrl?: string }[] = routine
    ? routine.movements.map((m: MovementStep) => {
        const s = STRETCHES_DATA.find((item) => item.id === m.stretchId || item.id === m.id);
        return {
          title: m.name,
          durationSeconds: m.durationSeconds || 120,
          description: m.description,
          arturoCue: m.verbalCue || s?.arturoCue,
          imageUrl: m.imageUrl || s?.imageUrl || routine.imageUrl,
        };
      })
    : stretch
    ? [
        {
          title: stretch.title,
          durationSeconds: stretch.defaultDurationSeconds || 60,
          description: stretch.description,
          arturoCue: stretch.arturoCue,
          imageUrl: stretch.imageUrl,
        },
      ]
    : [
        {
          title: 'Daily Stretch',
          durationSeconds: 60,
          description: 'Breathe deeply and hold.',
          imageUrl: 'https://lh3.googleusercontent.com/aida-public/AB6AXuCxFpH2eOsM80vVtv43n5GXRxdeiS0kf-5FYeHXrxcsvZ-2rXP_6kthEoqo8eTTGMYPASHhe2RkDyyMTaegpEZdVi8wDkvaf_mz0wFd3lufl7Mpq3R4KE91a2VgEmUHPQnGN0AM8RjPW_f7zsbCi5h4YbW_DT9BRJedFR0PG5K2no3HhI0mYapJirM0eUiNK7obnDxcO10nk6bxT7dsLdrdRKZ9uBCM2ciZtom3l5iJ_lxwAGdZ8fYx',
        },
      ];

  const [currentStepIdx, setCurrentStepIdx] = useState(
    initialStepIndex >= 0 && initialStepIndex < steps.length ? initialStepIndex : 0
  );

  const activeStep = steps[currentStepIdx];
  const [timeLeft, setTimeLeft] = useState(activeStep.durationSeconds);
  const [isPlaying, setIsPlaying] = useState(true);
  const [breathPhase, setBreathPhase] = useState<'Inhale' | 'Hold' | 'Exhale'>('Inhale');

  // Reset timer on step index change
  useEffect(() => {
    setTimeLeft(activeStep.durationSeconds);
    setIsPlaying(true);
    sound.playChime(432, 1.5);
  }, [currentStepIdx]);

  // Main countdown ticker
  useEffect(() => {
    let timer: NodeJS.Timeout | null = null;
    if (isPlaying && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (isPlaying && timeLeft === 0) {
      // Step complete
      sound.playCompletion();
      if (currentStepIdx < steps.length - 1) {
        setCurrentStepIdx((idx) => idx + 1);
      } else {
        // Complete whole session!
        const totalSecs = steps.reduce((acc, s) => acc + s.durationSeconds, 0);
        const mins = Math.max(1, Math.round(totalSecs / 60));
        const sessionTitle = routine ? routine.title : stretch ? stretch.title : 'Quick Stretch';
        onCompleteSession(mins, sessionTitle);
      }
    }
    return () => {
      if (timer) clearInterval(timer);
    };
  }, [isPlaying, timeLeft, currentStepIdx, steps]);

  // Breath rhythm generator (4s inhale, 2s hold, 4s exhale)
  useEffect(() => {
    let breathTimer: NodeJS.Timeout | null = null;
    if (isPlaying) {
      let cycle = 0;
      breathTimer = setInterval(() => {
        cycle = (cycle + 1) % 10;
        if (cycle < 4) setBreathPhase('Inhale');
        else if (cycle < 6) setBreathPhase('Hold');
        else setBreathPhase('Exhale');
      }, 1000);
    }
    return () => {
      if (breathTimer) clearInterval(breathTimer);
    };
  }, [isPlaying]);

  const togglePlay = () => {
    sound.playSoftClick();
    setIsPlaying(!isPlaying);
  };

  const handleNext = () => {
    sound.playSoftClick();
    if (currentStepIdx < steps.length - 1) {
      setCurrentStepIdx((idx) => idx + 1);
    } else {
      const totalSecs = steps.reduce((acc, s) => acc + s.durationSeconds, 0);
      const mins = Math.max(1, Math.round(totalSecs / 60));
      const sessionTitle = routine ? routine.title : stretch ? stretch.title : 'Quick Stretch';
      onCompleteSession(mins, sessionTitle);
    }
  };

  const handlePrev = () => {
    sound.playSoftClick();
    if (currentStepIdx > 0) {
      setCurrentStepIdx((idx) => idx - 1);
    } else {
      setTimeLeft(activeStep.durationSeconds);
    }
  };

  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  // SVG ring properties
  const radius = 110;
  const circumference = 2 * Math.PI * radius;
  const progressRatio = activeStep.durationSeconds > 0 ? timeLeft / activeStep.durationSeconds : 0;
  const strokeDashoffset = circumference * (1 - progressRatio);

  return (
    <div className="fixed inset-0 z-50 bg-[#0F0F10]/95 backdrop-blur-3xl flex flex-col justify-between p-6 md:p-10 select-none overflow-y-auto">
      {/* Top Bar */}
      <div className="flex items-center justify-between w-full max-w-xl mx-auto pt-2">
        <button
          onClick={() => {
            sound.playSoftClick();
            onClose();
          }}
          className="p-3 text-gray-300 hover:text-white rounded-full bg-[#1A1A1C] border border-white/10 transition-all"
          aria-label="Close timer"
        >
          <span className="material-symbols-outlined text-xl">close</span>
        </button>

        <div className="text-center">
          <span className="text-[10px] uppercase font-bold tracking-[0.2em] text-gray-500">
            {routine ? `ROUTINE: ${routine.title}` : 'STRETCH TIMER'}
          </span>
          <p className="text-sm font-semibold text-blue-400">
            Step {currentStepIdx + 1} of {steps.length}
          </p>
        </div>

        <button
          onClick={() => sound.playChime(528, 2.0)}
          className="p-3 text-gray-300 hover:text-white rounded-full bg-[#1A1A1C] border border-white/10 transition-all"
          aria-label="Sound chime"
        >
          <span className="material-symbols-outlined text-xl">volume_up</span>
        </button>
      </div>

      {/* Main Timer Display */}
      <div className="flex flex-col items-center justify-center my-auto py-4 gap-6 max-w-xl mx-auto w-full">
        {/* Step Title & Exercise Card Preview */}
        <div className="text-center px-4 flex flex-col items-center">
          {activeStep.imageUrl && (
            <div className="w-24 h-24 md:w-28 md:h-28 rounded-2xl overflow-hidden border border-white/10 shadow-lg bg-[#121214] mb-4 group relative">
              <img
                src={activeStep.imageUrl}
                alt={activeStep.title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-[#0F0F10]/40 to-transparent" />
            </div>
          )}
          <h2 className="text-2xl md:text-3xl font-light text-white tracking-tight">{activeStep.title}</h2>
          <p className="text-xs md:text-sm text-gray-400 mt-1 max-w-md line-clamp-2">{activeStep.description}</p>
        </div>

        {/* Circular SVG Ring & Time Counter */}
        <div className="relative w-[280px] h-[280px] md:w-[320px] md:h-[320px] flex items-center justify-center my-4">
          {/* Pulsing ambient glow ring */}
          <div
            className={`absolute inset-0 rounded-full bg-blue-600/20 blur-3xl transition-all duration-1000 ${
              breathPhase === 'Inhale' ? 'scale-110 opacity-80' : 'scale-95 opacity-30'
            }`}
          />

          <svg className="w-full h-full -rotate-90 transform">
            {/* Background Track */}
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              className="stroke-white/5"
              strokeWidth="8"
              fill="transparent"
            />
            {/* Animated Progress Ring */}
            <circle
              cx="50%"
              cy="50%"
              r={radius}
              className="stroke-blue-500 transition-all duration-1000 ease-linear"
              strokeWidth="8"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              strokeLinecap="round"
              fill="transparent"
            />
          </svg>

          {/* Center Timer Text & Breath Guidance */}
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            <span className="text-5xl md:text-6xl font-light text-white tracking-wider font-mono">
              {formatTime(timeLeft)}
            </span>
            <div className="mt-3 px-4 py-1 rounded-full bg-blue-600/20 border border-blue-500/30 text-[11px] font-semibold text-blue-400 tracking-wider uppercase transition-all duration-700">
              {breathPhase === 'Inhale' && 'Inhale to lengthen...'}
              {breathPhase === 'Hold' && 'Hold softly...'}
              {breathPhase === 'Exhale' && 'Exhale to release...'}
            </div>
          </div>
        </div>

        {/* Arturo's Cue quote if available */}
        {activeStep.arturoCue && (
          <p className="text-center text-sm italic text-blue-300 font-serif max-w-sm px-4">
            {activeStep.arturoCue}
          </p>
        )}
      </div>

      {/* Bottom Controls Bar */}
      <div className="flex flex-col items-center gap-6 w-full max-w-xl mx-auto pb-4">
        {/* Progress Bar for multi-step routines */}
        {steps.length > 1 && (
          <div className="w-full bg-[#1A1A1C] h-1.5 rounded-full overflow-hidden flex gap-1 p-0.5 border border-white/5">
            {steps.map((_, i) => (
              <div
                key={i}
                className={`h-full flex-1 rounded-full transition-all ${
                  i < currentStepIdx
                    ? 'bg-blue-500'
                    : i === currentStepIdx
                    ? 'bg-blue-600'
                    : 'bg-white/10'
                }`}
              />
            ))}
          </div>
        )}

        {/* Playback Controls */}
        <div className="flex items-center gap-6">
          <button
            onClick={handlePrev}
            className="w-12 h-12 rounded-full bg-[#1A1A1C] border border-white/10 text-gray-300 flex items-center justify-center hover:bg-white/10 hover:text-white active:scale-90 transition-all"
            aria-label="Previous step"
          >
            <span className="material-symbols-outlined text-2xl">skip_previous</span>
          </button>

          <button
            onClick={togglePlay}
            className="w-20 h-20 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-xl shadow-blue-900/40 hover:bg-blue-500 active:scale-95 transition-all"
            aria-label={isPlaying ? 'Pause' : 'Play'}
          >
            <span className="material-symbols-outlined text-4xl" style={{ fontVariationSettings: "'FILL' 1" }}>
              {isPlaying ? 'pause' : 'play_arrow'}
            </span>
          </button>

          <button
            onClick={handleNext}
            className="w-12 h-12 rounded-full bg-[#1A1A1C] border border-white/10 text-gray-300 flex items-center justify-center hover:bg-white/10 hover:text-white active:scale-90 transition-all"
            aria-label="Next step"
          >
            <span className="material-symbols-outlined text-2xl">skip_next</span>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { auth, googleProvider, signInWithPopup, signOut, User } from '../lib/firebase';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentUser: User | null;
}

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, currentUser }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleGoogleSignIn = async () => {
    setError(null);
    setLoading(true);
    try {
      await signInWithPopup(auth, googleProvider);
      setLoading(false);
      onClose();
    } catch (err: any) {
      console.error('Google Sign In Error:', err);
      setError(err.message || 'Failed to sign in with Google');
      setLoading(false);
    }
  };

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!email || !password) {
      setError('Please fill in all fields.');
      return;
    }
    setLoading(true);
    try {
      if (isSignUp) {
        await createUserWithEmailAndPassword(auth, email, password);
      } else {
        await signInWithEmailAndPassword(auth, email, password);
      }
      setLoading(false);
      onClose();
    } catch (err: any) {
      console.error('Email Auth Error:', err);
      setError(err.message || 'Authentication failed');
      setLoading(false);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut(auth);
      onClose();
    } catch (err: any) {
      setError(err.message);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fadeIn">
      <div className="relative w-full max-w-md bg-[#18181A] rounded-3xl border border-white/10 shadow-2xl p-6 flex flex-col gap-5">
        <div className="flex items-center justify-between border-b border-white/5 pb-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-blue-600/20 border border-blue-500/30 flex items-center justify-center text-blue-400">
              <span className="material-symbols-outlined text-lg">account_circle</span>
            </div>
            <h3 className="text-xl font-bold text-white tracking-tight">
              {currentUser ? 'Account Profile' : isSignUp ? 'Create Account' : 'Sign In to CenterFlow'}
            </h3>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 text-gray-400 hover:text-white rounded-full bg-white/5 hover:bg-white/10"
          >
            <span className="material-symbols-outlined text-lg">close</span>
          </button>
        </div>

        {error && (
          <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-xl text-xs text-red-300 flex items-center gap-2">
            <span className="material-symbols-outlined text-base">error</span>
            <span>{error}</span>
          </div>
        )}

        {currentUser ? (
          <div className="flex flex-col gap-4 py-2">
            <div className="flex items-center gap-4 p-4 bg-[#121214] rounded-2xl border border-white/5">
              {currentUser.photoURL ? (
                <img src={currentUser.photoURL} alt="Avatar" className="w-12 h-12 rounded-full border border-blue-500/40" />
              ) : (
                <div className="w-12 h-12 rounded-full bg-blue-600 flex items-center justify-center text-white font-bold text-lg">
                  {(currentUser.displayName || currentUser.email || 'U')[0].toUpperCase()}
                </div>
              )}
              <div className="flex flex-col">
                <span className="text-sm font-bold text-white">{currentUser.displayName || 'CenterFlow User'}</span>
